            if square <= filled:
                candidates.append((square, 1))

    by_cell = {cell: [] for cell in filled}
    for cells, color in candidates:
        for cell in cells:
            by_cell[cell].append((cells, color))

    def cover(remaining):
        if not remaining:
            return []
        cell = min(remaining)
        for cells, color in by_cell[cell]:
            if cells <= remaining:
                rest = cover(remaining - cells)
                if rest is not None:
                    return [(cells, color)] + rest
        return None

